mapper.select:
select di.id, di.name, di.category_id, di.price, di.image, di.description, di.status, di.update_time, dc.name as categoryName, df.id as flavor_id, df.dish_id, df.name as flavor_name, df.value as flavor_value from dish di left join category dc on di.category_id = dc.id left join dish_flavor df on di.id = df.dish_id
and di.name like concat('%', #{name}, '%')
and di.category_id = #{categoryId}
and di.status = #{status}
order by di.id desc
